import { randomUUID } from "node:crypto";
import { getCardImageUrl } from "../types.js";
import { GameCard } from "../domain-types.js";
import { currentTraceparent } from "./traceparent.js";

export function zoneHintForPlay(gameCard: GameCard): ZoneHint {
  return gameCard.card.cardTypes.includes("Land") ? "battlefield" : "stack";
}


export const CARD_PLAYED_EVENT_NAME = "card.played" as const;

export type ZoneHint = "stack" | "battlefield" | "graveyard";

export interface Initiator {
  seatId: string;
  playerName: string;
  sessionId?: string;
}

export type Significance = "physical" | "domain" | "administrative";

export interface EventEnvelope<Payload> {
  id: string;
  tableId: string;
  name: string;
  occurredAt: string;
  initiator: Initiator;
  occurredIn: "shuffler";
  origin: string;
  significance: Significance;
  traceparent: string;
  schemaVersion: number;
  payload: Payload;
}

export interface CardPlayedPayload {
  card: {
    scryfallId: string;
    instanceId: string;
  };
  face: "front" | "back";
  zoneHint: ZoneHint;
  frontImageUrl: string;
  backImageUrl: string | null;
  cardName: string;
  owner: string;
  isCommander: boolean;
  gameCardIndex: number;
}

export type CardPlayedEvent = EventEnvelope<CardPlayedPayload>;

// Shared by buildCardPlayedEvent and buildCardPlayedFaceDownEvent: the face/image facts
// are identical between a revealed play and a concealed one (concealment never touches
// which face was chosen underneath) — keep that computation in one place even though the
// two event kinds themselves stay deliberately separate.
function cardFaceFields(gameCard: GameCard): Pick<CardPlayedPayload, "face" | "frontImageUrl" | "backImageUrl"> {
  return {
    face: gameCard.currentFace,
    frontImageUrl: getCardImageUrl(gameCard.card, "normal", "front"),
    backImageUrl: gameCard.card.twoFaced ? getCardImageUrl(gameCard.card, "normal", "back") : null,
  };
}

export function buildCardPlayedEvent(
  gameCard: GameCard,
  instanceId: string,
  initiator: Initiator,
  owner: string,
  zoneHint: ZoneHint,
  tableName: string
): CardPlayedEvent {
  return {
    id: randomUUID(),
    tableId: tableName,
    name: CARD_PLAYED_EVENT_NAME,
    occurredAt: new Date().toISOString(),
    initiator: { seatId: initiator.seatId, playerName: initiator.playerName, sessionId: initiator.sessionId },
    occurredIn: "shuffler",
    origin: "shuffler.playCardSubmit",
    significance: "domain",
    traceparent: currentTraceparent(),
    schemaVersion: 1,
    payload: {
      card: {
        scryfallId: gameCard.card.scryfallId,
        instanceId,
      },
      ...cardFaceFields(gameCard),
      zoneHint,
      cardName: gameCard.card.name,
      owner,
      isCommander: gameCard.isCommander,
      gameCardIndex: gameCard.gameCardIndex,
    },
  };
}

export const CARD_PLAYED_FACE_DOWN_EVENT_NAME = "card.played-face-down" as const;

// Deliberate duplicate of CardPlayedPayload (per spec.md's Implementation Decisions):
// the shape is identical today, but the two kinds are meant to be free to diverge later
// without a retroactive schema version bump.
export interface CardPlayedFaceDownPayload {
  card: {
    scryfallId: string;
    instanceId: string;
  };
  face: "front" | "back";
  zoneHint: ZoneHint;
  frontImageUrl: string;
  backImageUrl: string | null;
  cardName: string;
  owner: string;
  isCommander: boolean;
  gameCardIndex: number;
}

export type CardPlayedFaceDownEvent = EventEnvelope<CardPlayedFaceDownPayload>;

export const CARD_RETURNED_EVENT_NAME = "card.returned" as const;

export interface CardReturnedPayload {
  card: {
    scryfallId: string;
    instanceId: string;
  };
  gameCardIndex: number;
  seat: string;
}

export type CardReturnedEvent = EventEnvelope<CardReturnedPayload>;

/** Any transition out of the Shuffler's own Table location — Return button, put-in-hand/top/bottom. */
export function buildCardReturnedEvent(gameCard: GameCard, instanceId: string, initiator: Initiator, seat: string, tableName: string): CardReturnedEvent {
  return {
    id: randomUUID(),
    tableId: tableName,
    name: CARD_RETURNED_EVENT_NAME,
    occurredAt: new Date().toISOString(),
    initiator: { seatId: initiator.seatId, playerName: initiator.playerName, sessionId: initiator.sessionId },
    occurredIn: "shuffler",
    origin: "shuffler.returnCardSubmit",
    significance: "domain",
    traceparent: currentTraceparent(),
    schemaVersion: 1,
    payload: {
      card: {
        scryfallId: gameCard.card.scryfallId,
        instanceId,
      },
      gameCardIndex: gameCard.gameCardIndex,
      seat,
    },
  };
}

export function buildCardPlayedFaceDownEvent(
  gameCard: GameCard,
  instanceId: string,
  initiator: Initiator,
  owner: string,
  zoneHint: ZoneHint,
  tableName: string
): CardPlayedFaceDownEvent {
  return {
    id: randomUUID(),
    tableId: tableName,
    name: CARD_PLAYED_FACE_DOWN_EVENT_NAME,
    occurredAt: new Date().toISOString(),
    initiator: { seatId: initiator.seatId, playerName: initiator.playerName, sessionId: initiator.sessionId },
    occurredIn: "shuffler",
    origin: "shuffler.playCardFaceDownSubmit",
    significance: "domain",
    traceparent: currentTraceparent(),
    schemaVersion: 1,
    payload: {
      card: {
        scryfallId: gameCard.card.scryfallId,
        instanceId,
      },
      ...cardFaceFields(gameCard),
      zoneHint,
      cardName: gameCard.card.name,
      owner,
      isCommander: gameCard.isCommander,
      gameCardIndex: gameCard.gameCardIndex,
    },
  };
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://github.com/jessitron/mtg-deck-shuffler/contracts/payloads/card.returned.v1.json",
  "title": "card.returned payload, schemaVersion 1",
  "description": "A card left the table. Bidirectional: sent tabletop->shuffler (dragged off the playmat back into the Shuffler's game state — ticket 12's library portal) and, as of ticket 07, shuffler->tabletop (any transition out of the Shuffler's own Table location — the Return button, or a crafted put-in-hand/top/bottom — via `occurredIn: \"shuffler\"`), so a consumer must branch on `occurredIn` rather than assume a direction. The table isn't authoritative for a table card's face, so unlike card.played/card.discarded this event carries no `face` field (two-faced-cards watch point 19) — `face` is explicitly blacklisted (`\"face\": false`) rather than merely undeclared, since a sender copying card.played's shape by habit is the likely mistake to guard against; every other unknown property still passes through per the fleet's additionalProperties:true policy. Identity is scryfallId plus gameCardIndex (the Shuffler's own decklist rank), same as always — `card.instanceId` is an additional, optional identifier: the Shuffler always has it for a Table card (minted at newGame, already used by card.played) and now sends it too, so the Tabletop can poof the matching shape by its `instanceId` prop; a tabletop-initiated send may omit it.",
  "type": "object",
  "properties": {
    "card": {
      "type": "object",
      "properties": {
        "scryfallId": {
          "type": "string",
          "format": "uuid",
          "description": "Definition: the exact printing — oracle identity, all faces, all names, all images derivable."
        },
        "instanceId": {
          "type": "string",
          "description": "The Shuffler's per-play GUID for this physical card (same value card.played sends). Optional — present on a shuffler-initiated card.returned (ticket 07, so the Tabletop can find the shape to remove); may be absent on a tabletop-initiated one."
        }
      },
      "required": ["scryfallId"],
      "additionalProperties": true
    },
    "gameCardIndex": {
      "type": "integer",
      "minimum": 0,
      "description": "The card's index in the Shuffler's initial decklist array (its alphabetical rank in that list) — how the Shuffler looks this card back up in its own game state."
    },
    "seat": {
      "type": "string",
      "minLength": 1,
      "description": "The seatId of the player this card is returning to — a bare non-empty check, matching card.played.v1's `owner` field."
    },
    "fromZone": {
      "type": "string",
      "minLength": 1,
      "description": "Where on the table the card was returning from. A hint — geography, not rules."
    },
    "face": false
  },
  "required": ["card", "gameCardIndex", "seat"],
  "additionalProperties": true
}

