          tableName: tableNameInput,
          playerName: playerNameInput || "player",
          seatId: prep.seatId ?? randomUUID().slice(0, 8),
        };
      }

      // Create new game from prep
      const gameId = persistStatePort.newGameId();
      const game = GameState.newGame(gameId, prep.prepId, prep.version, prep.deck, undefined, tableInfo, prep.sleeveColor, prep.playmatImagePath);
      game.startGame(browserTabId);

      trace.getActiveSpan()?.setAttributes({
        "deck.name": prep.deck.name,
        "commander.names": game.listCommanders().map((commander) => commander.card.name),
      });

      if (tableInfo) {
        const spineJoin = await joinSpineBestEffort(spinePort, {
          gameId,
          tableName: tableInfo.tableName,
          playerName: tableInfo.playerName,
          deckName: prep.deck.name,
          sleeveColor: prep.sleeveColor,
          playmatImagePath: prep.playmatImagePath,
          commanders: game.listCommanders(),
        });
        game.recordSpineJoin(spineJoin);
        if (spineJoin.seatId) {
          trace.getActiveSpan()?.setAttribute("seat.id", spineJoin.seatId);
        }
        // The Prep records all table info — that's what enables rejoining later.
        prep.tableName = tableInfo.tableName;
        prep.playerName = tableInfo.playerName;
        prep.seatId = game.seatId ?? tableInfo.seatId;
        prep.spineTableId = spineJoin.spineTableId;
        prep.spineSeatNumber = spineJoin.spineSeatNumber;
        prep.tableUrl = spineJoin.tableUrl;
        prep.updatedAt = new Date();
        await persistPrepPort.savePrep(prep);
      }

      await persistStatePort.save(game.toPersistedGameState());

      res.redirect(`/game/${gameId}`);
    } catch (error) {
      const errorMessage = error instanceof Error ? error.message : String(error);
      markCurrentSpanAsError(errorMessage, { "error.message": errorMessage, "error.type": error instanceof Error ? error.name : typeof error, "prep.id": prepId });
      log.error("game start failed", { "prep.id": prepId }, error);
      res.status(500).send(
        formatErrorPageHtmlPage({
          icon: "🎲",
          title: "Game Start Error",
          message: `Could not start game from preparation <strong>${prepId}</strong>.`,
          details: "There may be a technical issue with the game data.",
        })
      );
    }
  });

  // Returns active game page only
  app.get("/game/:gameId", async (req, res) => {
    const gameId = parseGameId(req.params.gameId);

    try {
      const persistedGame = await persistStatePort.retrieve(gameId);
      if (!persistedGame) {
        res.status(404).send(
          formatErrorPageHtmlPage({
            icon: "🎯",
            title: "Game Not Found",
            message: `Game <strong>${gameId}</strong> could not be found.`,
            details: "It may have expired or the ID might be incorrect.",
          })
        );
        return;
      }

      const game = await GameState.fromPersistedGameState(persistedGame, cardRepository);
      setCommonSpanAttributes({ tableName: game.tableName, playerName: game.playerName });

      // Only show active games; prep/review happens at /prepare/:prepId
      if (game.gameStatus() !== "Active") {
        res.status(400).send(
          formatErrorPageHtmlPage({
            icon: "⚠️",
            title: "Game Not Active",
            message: `Game <strong>${gameId}</strong> is not in an active state.`,
            details: "This game may have ended or not been started properly.",
